import java.util.*;

public class Solution {
    // Desloca só enquanto o anterior é ESTRITAMENTE maior: iguais não se cruzam → estável.
    static <T> void insertionSort(List<T> lista, Comparator<? super T> cmp) {
        for (int i = 1; i < lista.size(); i++) {
            T x = lista.get(i);
            int j = i - 1;
            while (j >= 0 && cmp.compare(lista.get(j), x) > 0) {
                lista.set(j + 1, lista.get(j));
                j--;
            }
            lista.set(j + 1, x);
        }
    }
}

