import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    record Pedido(String cliente, int valor) {}

    @Test void ordenaInteiros() {
        List<Integer> l = new ArrayList<>(List.of(5, 2, 9, 1, 5, 6));
        Solution.insertionSort(l, Comparator.naturalOrder());
        assertEquals(List.of(1, 2, 5, 5, 6, 9), l);
    }

    @Test void estavel() {
        List<Pedido> l = new ArrayList<>(List.of(
            new Pedido("ana", 30), new Pedido("bia", 10), new Pedido("caio", 30), new Pedido("davi", 10), new Pedido("eva", 20)));
        Solution.insertionSort(l, Comparator.comparingInt(Pedido::valor));
        assertEquals(List.of("bia", "davi", "eva", "ana", "caio"), l.stream().map(Pedido::cliente).toList());
    }

    @Test void bordas() {
        List<Integer> vazia = new ArrayList<>();
        Solution.insertionSort(vazia, Comparator.naturalOrder());
        assertEquals(List.of(), vazia);
        List<Integer> desc = new ArrayList<>(List.of(3, 2, 1));
        Solution.insertionSort(desc, Comparator.reverseOrder());
        assertEquals(List.of(3, 2, 1), desc);
    }
}

