import java.util.*;

public class Solution {
    static final Comparator<Integer> CRESCENTE = Integer::compare;
    static final Comparator<Long> DECRESCENTE_LONG = (a, b) -> Long.compare(b, a);
    static final Comparator<int[]> POR_X_DEPOIS_Y = Comparator.<int[]>comparingInt(p -> p[0]).thenComparingInt(p -> p[1]);
}

