import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void crescenteComExtremos() {
        List<Integer> l = new ArrayList<>(List.of(Integer.MAX_VALUE, -1, Integer.MIN_VALUE, 0));
        l.sort(Solution.CRESCENTE);
        assertEquals(List.of(Integer.MIN_VALUE, -1, 0, Integer.MAX_VALUE), l);
    }

    @Test void decrescenteLong() {
        List<Long> l = new ArrayList<>(List.of(1L, 5_000_000_000L, -5_000_000_000L));
        l.sort(Solution.DECRESCENTE_LONG);
        assertEquals(List.of(5_000_000_000L, 1L, -5_000_000_000L), l);
    }

    @Test void paresComExtremos() {
        List<int[]> l = new ArrayList<>(List.of(new int[]{1, Integer.MAX_VALUE}, new int[]{1, Integer.MIN_VALUE}, new int[]{Integer.MIN_VALUE, 0}));
        l.sort(Solution.POR_X_DEPOIS_Y);
        assertArrayEquals(new int[]{Integer.MIN_VALUE, 0}, l.get(0));
        assertArrayEquals(new int[]{1, Integer.MIN_VALUE}, l.get(1));
        assertArrayEquals(new int[]{1, Integer.MAX_VALUE}, l.get(2));
    }
}
